#include <stdio.h>

const int MAX_V = 10000;

int main() {
    int n, p, q;
    bool prime[MAX_V + 1] = {false}; // Use bool for memory efficiency

    // Initialize the prime array using the Sieve of Eratosthenes
    for (int i = 2; i * i <= MAX_V; i++) {
        if (!prime[i]) {
            for (int k = i * i; k <= MAX_V; k += i) {
                prime[k] = true; // Marking non-prime
            }
        }
    }

    while (1) {
        scanf("%d", &n);
        if (n == 0) break;

        for (int i = n; i >= 3; i--) {
            if (!prime[i] && !prime[i - 2]) { // Check for twin primes
                p = i;
                q = p - 2;
                break;
            }
        }

        printf("%d %d\n", q, p);
    }

    return 0;
}

